{"path":"/testbed/src/payhook/receiver.py","content":""""Adapter for billing provider payment notifications.

See docs/provider-notifications.md for the wire format: UTF-8 JSON bodies,
a decimal ``X-Pay-Timestamp`` (fresh within 300 seconds of ``now``), and a
``X-Pay-Signature: v1=<hex digest>`` header carrying an HMAC-SHA256 over the
ASCII timestamp, a single ``.`` byte, and the exact received body bytes.
"""

import hashlib
import hmac
import json
import re
from collections.abc import Mapping

from payhook.errors import InvalidNotification

_TIMESTAMP_HEADER = "X-Pay-Timestamp"
_SIGNATURE_HEADER = "X-Pay-Signature"
_SIGNATURE_SCHEME = "v1="
_MAX_CLOCK_DRIFT_SECONDS = 300

_DECIMAL_RE = re.compile(r"[0-9]+")
_SHA256_HEX_DIGEST_RE = re.compile(r"[0-9a-fA-F]{64}")
_CURRENCY_RE = re.compile(r"[A-Z]{3}")


def _body_bytes(raw_body):
    """Return the raw request body as bytes."""
    try:
        return bytes(raw_body)
    except TypeError:
        raise InvalidNotification("request body must be bytes") from None


def _lookup_header(headers, name):
    """Case-insensitive header lookup; returns the value or None."""
    if isinstance(headers, Mapping):
        target = name.lower()
        for key, value in headers.items():
            if isinstance(key, str) and key.lower() == target:
                return value
    return None


def _ascii_bytes(value):
    """Return the header value as ASCII bytes, or None if not ASCII text."""
    if isinstance(value, str):
        try:
            return value.encode("ascii")
        except UnicodeEncodeError:
            return None
    if isinstance(value, (bytes, bytearray)):
        try:
            bytes(value).decode("ascii")
        except UnicodeDecodeError:
            return None
        return bytes(value)
    return None


def _secret_key(secret):
    """Return the configured secret as bytes."""
    if isinstance(secret, str):
        return secret.encode("utf-8")
    if isinstance(secret, (bytes, bytearray)):
        return bytes(secret)
    raise InvalidNotification("invalid secret")


def parse_payment(raw_body, headers, secret, now):
    """Return an accepted payment in the billing worker's normalized format.

    Authenticates the delivery (timestamp freshness plus the ``v1``
    HMAC-SHA256 signature) before trusting the JSON body, then extracts the
    required payment fields into a new dictionary. Raises
    ``InvalidNotification`` for anything that cannot be accepted.
    """
    body = _body_bytes(raw_body)

    # Timestamp: present, decimal ASCII, and fresh relative to ``now``.
    timestamp_bytes = _ascii_bytes(_lookup_header(headers, _TIMESTAMP_HEADER))
    if (
        timestamp_bytes is None
        or _DECIMAL_RE.fullmatch(timestamp_bytes.decode("ascii")) is None
    ):
        raise InvalidNotification("missing or malformed timestamp")
    timestamp = int(timestamp_bytes)
    if abs(timestamp - now) > _MAX_CLOCK_DRIFT_SECONDS:
        raise InvalidNotification("stale timestamp")

    # Signature: v1=<hex>, HMAC-SHA256 over "<timestamp>.<exact body bytes>",
    # compared in constant time.
    signature_bytes = _ascii_bytes(_lookup_header(headers, _SIGNATURE_HEADER))
    if signature_bytes is None:
        raise InvalidNotification("missing or malformed signature")
    signature = signature_bytes.decode("ascii")
    if not signature.startswith(_SIGNATURE_SCHEME):
        raise InvalidNotification("unsupported signature scheme")
    digest_hex = signature[len(_SIGNATURE_SCHEME):]
    if _SHA256_HEX_DIGEST_RE.fullmatch(digest_hex) is None:
        raise InvalidNotification("malformed signature digest")
    expected_digest = hmac.new(
        _secret_key(secret), timestamp_bytes + b"." + body, hashlib.sha256
    ).digest()
    if not hmac.compare_digest(bytes.fromhex(digest_hex), expected_digest):
        raise InvalidNotification("signature mismatch")

    # Body: UTF-8 JSON object carrying the required payment fields.
    try:
        payload = json.loads(body)
    except ValueError:
        raise InvalidNotification("malformed JSON body") from None
    if not isinstance(payload, dict):
        raise InvalidNotification("body must be a JSON object")

    event_id = payload.get("event_id")
    account_id = payload.get("account_id")
    amount_minor = payload.get("amount_minor")
    currency = payload.get("currency")

    if not isinstance(event_id, str) or not event_id:
        raise InvalidNotification("invalid event_id")
    if not isinstance(account_id, str) or not account_id:
        raise InvalidNotification("invalid account_id")
    # bool is an int subclass, but booleans are not amounts.
    if isinstance(amount_minor, bool) or not isinstance(amount_minor, int):
        raise InvalidNotification("invalid amount_minor")
    if amount_minor < 0:
        raise InvalidNotification("invalid amount_minor")
    if not isinstance(currency, str) or _CURRENCY_RE.fullmatch(currency) is None:
        raise InvalidNotification("invalid currency")

    return {
        "event_id": event_id,
        "account_id": account_id,
        "amount_minor": amount_minor,
        "currency": currency,
    }
"}

